      await this.daprClient.state.save(redisStoreAmr, [dataToCache]);
    } catch (error) {
      this.customLogger.error(
        `Error saving list of plant in Redis: ${error}`,
        context,
        error.stack,
      );
    }
  }
}

/**
 * Default catch function that returns the error as the specified type.
 * @param error - The error caught in the try block.
 * @returns The error cast to the specified type.
 */
function defaultCatchFunction<TError>(error: Error): TError {
  return error as unknown as TError;
}

/**
 * A utility function that wraps try-catch logic in a consistent return format.
 *
 * This function can be called either with a function:
 * `asyncTryCatch(() => Promise<T>)`
 *
 * Or with an object containing `tryFn` and an optional `catchFn`:
 * `asyncTryCatch({ tryFn: () => Promise<T>, catchFn?: (err) => TError })`
 * @param optionsOrTryFunction - Either a function to execute, or an object with `tryFn` (required) and `catchFn` (optional).
 * @returns A tuple: [result or undefined, error or undefined].
 */
export async function asyncTryCatch<T, TError = Error>(
  optionsOrTryFunction:
    | (() => Promise<T>)
    | {
        /**
         * The function to attempt execution of.
         */
        tryFn: () => Promise<T>;

        /**
         * Optional catch handler to customize the returned error.
         */
        catchFn?: (error: Error) => Promise<TError> | TError;
      },
): Promise<[T | undefined, TError | undefined]> {
  try {
    if (typeof optionsOrTryFunction === 'function') {
      return [await optionsOrTryFunction(), undefined];
    }

    return [await optionsOrTryFunction.tryFn(), undefined];
  } catch (error_) {
    const error = error_ instanceof Error ? error_ : new Error(String(error_));
    const catchFunction =
      typeof optionsOrTryFunction !== 'function' && optionsOrTryFunction.catchFn
        ? optionsOrTryFunction.catchFn
        : defaultCatchFunction;

    return [undefined, await catchFunction(error)];
  }
}

/**
 * Wraps a promise with a timeout. If the promise does not resolve or reject
 * within the specified time, the returned promise is rejected with a timeout error.
 * @template T - The resolved type of the input promise.
 * @param promise - The promise to wrap with a timeout.
 * @param ms - Timeout duration in milliseconds.
 * @returns A promise that resolves with the input promise or rejects if the timeout is exceeded.
 * @throws {Error} Throws "Operation timed out" if the promise does not settle within the given time.
 */
export async function withTimeout<T>(
  promise: Promise<T>,
  ms: number,
): Promise<T> {
  let timeoutId: ReturnType<typeof setTimeout>;
  const timeoutPromise = new Promise<never>((_, reject) => {
    timeoutId = setTimeout(() => reject(new Error('Operation timed out')), ms);
  });
  return Promise.race([promise, timeoutPromise]).finally(() =>
    clearTimeout(timeoutId),
  );
}

