import { CosmosClient } from '@azure/cosmos';
import { DefaultAzureCredential } from '@azure/identity';
import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { AppLogger } from '@/common/logger/app-logger';
import { CosmosDatabaseConfigService } from '@/config/cosmos-db/cosmos.database.service';
import { ContainerDto } from '@/modules/container/dtos/container.dto';
import { UpsertContainerDto } from '@/modules/container/dtos/upsert-container.dto';

@Injectable()
export class ContainerCosmosDatabaseService {
  private readonly client: CosmosClient;

  private readonly database;

  private readonly container;

  public constructor(
    private readonly cosmosDatabasebService: CosmosDatabaseConfigService,
    private readonly customLogger: AppLogger,
  ) {
    // Create DefaultAzureCredential with the user-assigned managed identity's Client ID
    const credential = new DefaultAzureCredential();

    this.client = new CosmosClient({
      aadCredentials: credential,
      endpoint: this.cosmosDatabasebService.cosmosDbEndpoint,
    });

    this.database = this.client.database(
      this.cosmosDatabasebService.cosmosDbDatabase,
    );
    this.container = this.database.container(
      this.cosmosDatabasebService.cosmosDbContainer,
    );
  }

  public async partitionKeyExist(partitionKeyValue: string): Promise<boolean> {
    const context: JobsLogContext = {
      method: 'partitionKeyExist',
      service: 'ContainerCosmosDatabaseService',
    };
    try {
      // SQL query to check for the existence of a specific partition key value
      const querySpec = {
        parameters: [
          {
            name: '@partitionKeyValue',
            value: Number(partitionKeyValue),
          },
        ],
        query:
          'SELECT VALUE COUNT(1) FROM c WHERE c.plant = @partitionKeyValue',
      };

      // Execute the query against the Cosmos container
      const { resources: results } = await this.container.items
        .query(querySpec)
        .fetchAll();

      // Check if the count is greater than 0
      return results.length > 0 && results[0] > 0; // Return true if the partition key exists
    } catch (error) {
      this.customLogger.error(
        `Plant ${partitionKeyValue} Error checking partition key existence in Cosmos DB: ${error}`,
        context,
      );
      return false; // Return false in case of error
    }
  }

  public async findElementByIdAndPartitionKey(
    partitionKey: number,
    id: string,
  ): Promise<boolean> {
    const context: JobsLogContext = {
      method: 'findElementByIdAndPartitionKey',
      service: 'ContainerCosmosDatabaseService',
    };
    try {
      const querySpec = {
        parameters: [
          { name: '@id', value: id },
          { name: '@partitionKey', value: partitionKey },
        ],
        query: `SELECT * FROM c WHERE c.id = @id AND c.plant = @partitionKey`,
      };

      const { resources } = await this.container.items
        .query(querySpec)
        .fetchAll();

      return resources.length > 0; // Return the first match or null
    } catch (error) {
      this.customLogger.error(
        `Error querying document: ${error.message}`,
        context,
        error.stack,
      );
      return false;
    }
  }

  public async upsertContainer(
    containerData: UpsertContainerDto,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'upsertContainer',
      service: 'ContainerCosmosDatabaseService',
    };
    try {
      const containerDataWithId = {
        ...containerData,
        id: containerData.containerId,
      };

      this.container.items.upsert(containerDataWithId).catch((error) => {
        this.customLogger.error(
          `Failed to upsert container data  with ID ${containerDataWithId.id}: ${error.message}`,
          context,
          error.stack,
        );
      });

      // Wait for all upsert operations in the batch to complete
      this.customLogger.debug(
        `Successfully upserted ${containerDataWithId.id} container id .`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Error upserting container into Cosmos DB: ${error.message}`,
        context,
        error.stack,
      );
      throw error; // Optionally rethrow the error for further handling
    }
  }

  public async deleteContainer(containerData: ContainerDto): Promise<void> {
    const context: JobsLogContext = {
      method: 'deleteContainer',
      service: 'ContainerCosmosDatabaseService',
    };
    try {
      await this.container
        .item(containerData.containerId, containerData.plant)
        .delete();
    } catch (error) {
      this.customLogger.error(
        ` Plant ${containerData.plant} Error deleting container   ${containerData.containerId}  from Cosmos DB: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  public async getContainer(
    containerId: string,
    plant: number,
  ): Promise<UpsertContainerDto | undefined> {
    const context: JobsLogContext = {
      method: 'getContainer',
      service: 'ContainerCosmosDatabaseService',
    };
    try {
      const querySpec = {
        parameters: [
          { name: '@id', value: containerId },
          { name: '@partitionKey', value: plant },
        ],
        query: `SELECT * FROM c WHERE c.id = @id AND c.plant = @partitionKey`,
      };

      const { resources } = await this.container.items
        .query(querySpec)
        .fetchAll();

      if (resources.length > 0) {
        return resources[0] as UpsertContainerDto;
      }
      return undefined;
    } catch (error) {
      this.customLogger.error(
        `Error retrieving container from Cosmos DB: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }
}

import { Module } from '@nestjs/common';
import { ConfigModule } from '@nestjs/config';
