@Module({
  exports: [ContainerCosmosDatabaseService, TransferLogDatabaseService],
  imports: [ConfigModule, CosmosDatabaseConfigModule],
  providers: [ContainerCosmosDatabaseService, TransferLogDatabaseService],
})
export class CosmosDatabaseModule {}

import { CosmosClient } from '@azure/cosmos';
import { DefaultAzureCredential } from '@azure/identity';
import { JobsLogContext } from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { AppLogger } from '@/common/logger/app-logger';
import { CosmosDatabaseConfigService } from '@/config/cosmos-db/cosmos.database.service';
import { TransferLogDto } from '@/modules/transfer-log/dtos/transfer-log.dto';

@Injectable()
export class TransferLogDatabaseService {
  private readonly client: CosmosClient;

  private readonly database;

  private readonly container;

  public constructor(
    private readonly cosmosDatabasebService: CosmosDatabaseConfigService,
    private readonly customLogger: AppLogger,
  ) {
    // Create DefaultAzureCredential with the user-assigned managed identity's Client ID
    const credential = new DefaultAzureCredential();

    this.client = new CosmosClient({
      aadCredentials: credential,
      endpoint: this.cosmosDatabasebService.cosmosDbEndpoint,
    });

    this.database = this.client.database(
      this.cosmosDatabasebService.cosmosDbDatabase,
    );
    this.container = this.database.container(
      this.cosmosDatabasebService.cosmosDbTransfer,
    );
  }

  public async findTransferByIdAndPartitionKey(
    partitionKey: number,
    id: number,
  ): Promise<boolean> {
    const context: JobsLogContext = {
      method: 'findTransferByIdAndPartitionKey',
      service: 'TransferLogDatabaseService',
    };
    try {
      const querySpec = {
        parameters: [
          { name: '@id', value: id },
          { name: '@partitionKey', value: partitionKey },
        ],
        query: `SELECT * FROM c WHERE c.id = @id AND c.plant = @partitionKey`,
      };

      const { resources } = await this.container.items
        .query(querySpec)
        .fetchAll();

      return resources.length > 0; // Return the first match or null
    } catch (error) {
      this.customLogger.error(
        `Error querying document: ${error.message}:`,
        context,
        error.stack,
      );
      return false;
    }
  }

  public async upsertTransferLog(
    transferLogData: TransferLogDto,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'upsertTransferLog',
      service: 'TransferLogDatabaseService',
    };
    try {
      const transferLogDataWithId = {
        ...transferLogData,
        id: transferLogData.seqNum.toString(),
      };

      this.container.items.upsert(transferLogDataWithId).catch((error) => {
        this.customLogger.error(
          `Failed to upsert transfer log data with ID ${transferLogDataWithId.id}: ${error.message}`,
          context,
          error.stack,
        );
      });

      // Wait for all upsert operations in the batch to complete
      this.customLogger.debug(
        `Successfully upserted ${transferLogDataWithId.id} transfer log id.`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Error upserting transfer log into Cosmos DB: ${error.message}`,
        context,
        error.stack,
      );
      throw error; // Optionally rethrow the error for further handling
    }
  }

  public async deleteTransferLog(
    transferLogData: TransferLogDto,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'deleteTransferLog',
      service: 'TransferLogDatabaseService',
    };
    try {
      await this.container
        .item(transferLogData.seqNum.toString(), transferLogData.plant)
        .delete();
    } catch (error) {
      this.customLogger.error(
        ` Plant ${transferLogData.plant} Error deleting transfer log ${transferLogData.seqNum} from Cosmos DB: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  public async getTransferLog(
    seqNumber: number,
    plant: number,
  ): Promise<TransferLogDto | undefined> {
    const context: JobsLogContext = {
      method: 'getTransferLog',
      service: 'TransferLogDatabaseService',
    };
    try {
      const querySpec = {
        parameters: [
          { name: '@id', value: seqNumber },
          { name: '@partitionKey', value: plant },
        ],
        query: `SELECT * FROM c WHERE c.id = @id AND c.plant = @partitionKey`,
      };

      const { resources } = await this.container.items
        .query(querySpec)
        .fetchAll();

      if (resources.length > 0) {
        return resources[0] as TransferLogDto;
      }
      return undefined;
    } catch (error) {
      this.customLogger.error(
        `Error retrieving transfer log from Cosmos DB: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  public async findTransferBySeqNumAndPartitionKey(
    plant: number | string,
    seqNumber: number,
  ): Promise<TransferLogDto | null> {
    const querySpec = {
      query: 'SELECT * FROM c WHERE c.plant = @plant AND c.seqNum = @seqNum',
      parameters: [
        { name: '@plant', value: String(plant) },
        { name: '@seqNum', value: seqNumber },
      ],
    };

    const { resources } = await this.container.items
      .query(querySpec)
      .fetchAll();

    return resources.length > 0 ? (resources[0] as TransferLogDto) : null;
  }
}

import { JobsLogContext } from '@mesx/common-lib';
