import { EventEmitter2 } from '@nestjs/event-emitter';

import { DaprClient } from 'dapr-client';

import { PlantsResponseDto } from '@/common/api/dtos/plant.response.dto';
import { PlantHierarchyApi } from '@/common/api/plt-hry.api';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { MappingService } from '@/common/mapping/service/mapping.service';

import { SubscribeMessageService } from '@/common/subscribe/subscribe.service';

import { RedisConfigService } from '@/config/redis/redis-store/redis-store.service';

import { CombinedDtoWithIndex } from '@/dapr/dtos/combined.dto';
import { RedisMessage } from '@/dapr/interface/redis-message-data.interface';
import { getListPlant } from '@/helpers/caches/get-plant-list';
import { emitCosmosEvent } from '@/helpers/events/emit-sql-events';

import {
  decrementPendingMessageCount,
  incrementPendingMessageCount,
} from '@/helpers/statistics/pending-message-stats';
import { checkPayloadConsistency } from '@/helpers/validations/check-payload-consistency';
import { checkPlantConsistency } from '@/helpers/validations/check-plant-consistency';
import { EwmPlantCacheService } from '@/modules/ewm-plant-cache/ewm-plant-cache.service';

@Injectable()
export class DaprServiceApi implements OnModuleInit {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return { method, object, plant, service: DaprServiceApi.name, userId };
  }

  private plantList: Array<PlantsResponseDto> = [];

  private readonly daprClient: DaprClient;

  public constructor(
    private readonly mappingService: MappingService,
    private readonly eventEmitter: EventEmitter2,
    private readonly redisConfigService: RedisConfigService,
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly customLogger: AppLogger,
    private readonly ewmPlantCacheService: EwmPlantCacheService,
    private readonly plantHYRApi: PlantHierarchyApi,
  ) {
    this.daprClient = new DaprClient();
  }

  public async onModuleInit(): Promise<void> {
    await this.initializePlant();
  }

  public async initializePlant(): Promise<void> {
    this.plantList = await getListPlant(
      this.customLogger,
      this.daprClient,
      this.subscribeMessageService,
      this.redisConfigService.redisStoreAmr,
      this.redisConfigService.redisPlantKey,
      this.plantHYRApi,
    );
    await this.ewmPlantCacheService.synchronizeInMemoryPlants(this.plantList);
    await this.ewmPlantCacheService.synchronizeInMemoryWorkCenters();
    await this.ewmPlantCacheService.synchronizeInMemoryMaterials();
    await this.ewmPlantCacheService.synchronizeInMemoryStorageLocations();
  }

  private async processMessage(
    message: RedisMessage,
    sequenceNumber: string | Array<string> | undefined,
  ): Promise<void> {
    const { mappedData, destination, operation } = message;
    const plant = mappedData?.plant;
    const context = DaprServiceApi.createLogContext('processMessage', plant);
    this.customLogger.debug(
      `============== ${sequenceNumber} start processing message =======================`,
      context,
    );
    try {
      if (!operation) return;

      await emitCosmosEvent(
        this.customLogger,
        context,
        this.eventEmitter,
        destination,
        mappedData,
        operation,
      );
      this.customLogger.debug(
        `============== ${sequenceNumber} After Emit event =======================`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Error processing Message for ${destination}: ${error.message}`,
        context,
      );
    }
  }

  /**
   * Message handler
   * @param record - The record to handle
   * @param sequenceNumber - The sequence number of the message
   * @returns Start the dapr server
   */
  public async handleMessage(
    record: CombinedDtoWithIndex,
    sequenceNumber: string | Array<string> | undefined,
  ): Promise<void> {
    incrementPendingMessageCount();
    const dateStart = Date.now();
    const context = DaprServiceApi.createLogContext('handleMessage');
    try {
      if (!checkPayloadConsistency(this.customLogger, context, record)) return;

      const { __source_table: sourceTable, __op: operation } = record;
      this.customLogger.debug(
        `Received - operation: ${operation} - payload: ${JSON.stringify(record)}`,
        context,
      );
      if (!sourceTable) return;

      const { mappedData, destination, ingestionEventTracking } =
        this.mappingService.mapData(sourceTable, record, this.plantList);
      // Check first if there is two table source in the mapping system
      // Fifo check
      this.customLogger.debug(
        `Mapped Data:${JSON.stringify(mappedData)}`,
        context,
      );
      if (!checkPlantConsistency(this.customLogger, mappedData, this.plantList))
        return;

      const newRecord = {
        destination,
        ingestionEventTracking,
        mappedData,
        operation,
        sourceTable,
      };
      await this.processMessage(newRecord, sequenceNumber);
    } catch (error) {
      this.customLogger.error(
        `Error handling Message: ${error.stack ?? error.message ?? JSON.stringify(error)}`,
        context,
      );
    } finally {
      if (record) {
        await execAndLog(
          this.customLogger,

          async () => {},
          {
            name: 'handleMessage function runtime',
            srcLocation: 'handleMessage',
          },
          {
            record,
          },
          dateStart,
        );
      }
      decrementPendingMessageCount();
    }
  }
}

import { telemetryMetrics, PROCESSING_STATUS } from '@mesx/common-lib';
