// Environment variables
const bindings = {
  bindingContainer:
    process.env
      .INPUT_BINDINGS_MES_FAURECIA_DBO_HU_DTL_CONTENT_EWM_GATEWAY_BACKEND,
  bindingEkanbanTemp:
    process.env
      .INPUT_BINDINGS_MES_FAURECIA_DBO_EKANBAN_TEMP_EWM_GATEWAY_BACKEND,
  bindingTransferLog:
    process.env
      .INPUT_BINDINGS_MES_FAURECIA_DBO_TRANSFER_LOG_EWM_GATEWAY_BACKEND,
  topicMaterials: process.env.TOPIC_MATERIALS,
  topicPlants: process.env.TOPIC_EWM_PLANT_UPDATES,
  topicStorageLocations: process.env.TOPIC_STORAGE_LOCATIONS,
  topicWorkcenters: process.env.TOPIC_WORKCENTERS,
};

@Controller('')
export class DaprController {
  public constructor(
    private readonly daprService: DaprService,
    private readonly customLogger: AppLogger,
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly daprServiceApi: DaprServiceApi,
    private readonly eventhubSdkConfigService: EventhubSdkConfigService,
  ) {}

  /**
   * Process a standard event with common logging
   * @param request Request
   * @param methodName Method name for logging
   * @param topic Topic name for telemetry
   * @returns Promise<string>
   */
  private async processStandardEvent(
    request: Request,
    methodName: string,
    topic: string,
  ): Promise<string> {
    const event = request.body;
    const plantCode = event?.S_SITE || event?.PLANT;
    const startTime = Date.now();

    if (topic) {
      try {
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.RECEIVED,
          plantCode,
          topic,
        );
      } catch {
        // Silent fail - don't break processing if telemetry fails
      }
    }
    try {
      const result = await this.daprService.handleMessage(event);
      if (result.processed) {
        const duration = Date.now() - startTime;
        telemetryMetrics.trackEventProcessingDuration(
          duration,
          PROCESSING_STATUS.PROCESSED,
          String(plantCode),
          topic,
        );
        telemetryMetrics.trackEventProcessed(
          PROCESSING_STATUS.PROCESSED,
          String(plantCode),
          topic,
        );
      }
      return `OK${methodName}`;
    } catch (error) {
      const duration = Date.now() - startTime;
      telemetryMetrics.trackEventProcessingDuration(
        duration,
        PROCESSING_STATUS.INVALID,
        String(plantCode),
        topic,
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.INVALID,
        String(plantCode),
        topic,
      );
      throw error;
    }
  }

  @Post(bindings.bindingContainer)
  public async receiveEventContainer(@Req() request: Request): Promise<string> {
    if (await this.eventhubSdkConfigService.useEventhubSDK()) {
      this.customLogger.log('Dapr binding skipped - EventHub SDK is active', {
        method: 'receiveEventContainer',
        service: 'DaprController',
      });
      return 'OK (SDK Active)';
    }
    return this.processStandardEvent(
      request,
      'receiveEventContainer',
      'Container',
    );
  }

  @Post(bindings.bindingEkanbanTemp)
  public async receiveEventEkanbanTemp(
    @Req() request: Request,
  ): Promise<string> {
    return this.processStandardEvent(
      request,
      'receiveEventEkanbanTemp',
      'EkanbanTemp',
    );
  }

  @Post(bindings.bindingTransferLog)
  public async receiveEventTransferLog(
    @Req() request: Request,
  ): Promise<string> {
    if (await this.eventhubSdkConfigService.useEventhubSDK()) {
      this.customLogger.log('Dapr binding skipped - EventHub SDK is active', {
        method: 'receiveEventTransfer',
        service: 'DaprController',
      });
      return 'OK (SDK Active)';
    }
    return this.processStandardEvent(
      request,
      'receiveEventTransferLog',
      'TransferLog',
    );
  }

  @Post(bindings.topicMaterials)
  public async initMaterials(): Promise<string> {
    const context = DaprService.createLogContext('initMaterials');
    try {
      await this.daprService.handleMaterialMessage();
      this.customLogger.debug(`Updated Materials List`, context);
      return 'OK';
    } catch (error) {
      this.customLogger.error(
        `Error processing event: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  @Post(bindings.topicPlants)
  public async initPlant(@Req() request: Request): Promise<string> {
    const context = DaprService.createLogContext('initPlant');
    try {
      const data = request.body;
      await this.subscribeMessageService.handleMessage(data);
      await this.daprService.initializePlant();
      await this.daprServiceApi.initializePlant();
      this.customLogger.debug(`Updated Plants List`, context);
      return 'OK';
    } catch (error) {
      this.customLogger.error(
        `Error processing event: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  @Post(bindings.topicStorageLocations)
  public async initStorageLocations(): Promise<string> {
    const context = DaprService.createLogContext('initStorageLocations');
    try {
      await this.daprService.handleStorageLocationMessage();
      this.customLogger.debug(`Updated Storage Locations List`, context);
      return 'OK';
    } catch (error) {
      this.customLogger.error(
        `Error processing event: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  @Post(bindings.topicWorkcenters)
  public async initWorkcenters(): Promise<string> {
    const context = DaprService.createLogContext('initWorkcenters');
    try {
      await this.daprService.handleWorkcenterMessage();
      this.customLogger.debug(`Updated Workcenters List`, context);
      return 'OK';
    } catch (error) {
      this.customLogger.error(
        `Error processing event: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }
}

