@Injectable()
export class DaprService implements OnModuleInit, BeforeApplicationShutdown {
  public static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return { method, object, plant, service: DaprService.name, userId };
  }

  private readonly serviceMutexes: Record<string, Mutex> = {};

  private processingQueue: Record<string, boolean> = {
    container: false,
    transferLog: false,
    ekanbanTemp: false,
  };

  private plantList: Array<PlantsResponseDto> = [];

  private readonly inMemoryQueue: {
    container: Array<RedisMessage>;
    transferLog: Array<RedisMessage>;
    ekanbanTemp: Array<RedisMessage>;
  } = {
    container: [],
    transferLog: [],
    ekanbanTemp: [],
  };

  private readonly daprClient: DaprClient;

  public constructor(
    private readonly eventEmitter: EventEmitter2,
    private readonly mappingService: MappingService,
    private readonly redisConfigService: RedisConfigService,
    private readonly fileShareConfigService: FileShareConfigService,
    private readonly ingestionEventTrackingService: IngestionEventTrackingService,
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly ewmPlantCacheService: EwmPlantCacheService,
    private readonly plantHYRApi: PlantHierarchyApi,
    private readonly eventhubService: EventhubService,
    private readonly customLogger: AppLogger,
  ) {
    this.daprClient = new DaprClient();
    this.serviceMutexes.container = new Mutex();
    this.serviceMutexes.transferLog = new Mutex();
    this.serviceMutexes.ekanbanTemp = new Mutex();
  }

  public async initializePlant(): Promise<void> {
    this.plantList = await getListPlant(
      this.customLogger,
      this.daprClient,
      this.subscribeMessageService,

      this.redisConfigService.redisStoreAmr,

      this.redisConfigService.redisPlantKey,
      this.plantHYRApi,
    );
    await this.ewmPlantCacheService.synchronizeInMemoryPlants(this.plantList);
    await this.ewmPlantCacheService.synchronizeInMemoryWorkCenters();
    await this.ewmPlantCacheService.synchronizeInMemoryMaterials();
    await this.ewmPlantCacheService.synchronizeInMemoryStorageLocations();
  }

  private checkAndProcessQueues(): void {
    const context: JobsLogContext = {
      method: 'checkAndProcessQueues',
      service: 'DaprService',
    };
    for (const [queueName, queueData] of Object.entries(this.inMemoryQueue)) {
      if (queueData && queueData.length > 0) {
        if (this.processingQueue[queueName]) {
          this.customLogger.debug(
            `Queue ${queueName} is already being processed, skipping.`,
            context,
          );
        } else {
          this.processMessageQueue(queueName);
        }
      } else {
        this.customLogger.debug(
          `Queue ${queueName} is empty, skipping processing.`,
          context,
        );
      }
    }
  }

  private async initializeQueues(): Promise<void> {
    const { queueBackupBasePath } = this.fileShareConfigService;
    const microServiceName = 'ewm-gateway-be';
    await loadQueuesFromFileShare(
      this.customLogger,
      queueBackupBasePath,
      microServiceName,
      this.inMemoryQueue,
    );
    this.checkAndProcessQueues();
  }

  /**
   * Handles tasks that need to be performed before the application shuts down.
   * @param signal - The signal that triggered the shutdown.
   * @returns A promise that resolves when the shutdown tasks are complete.
   */
  public async beforeApplicationShutdown(signal: string): Promise<void> {
    const { queueBackupBasePath } = this.fileShareConfigService;
    const microServiceName = 'ewm-gateway-be';
    await beforeApplicationShutdown(
      this.customLogger,
      this.inMemoryQueue,
      queueBackupBasePath,
      microServiceName,
      signal,
    );
  }

  public async onModuleInit(): Promise<void> {
    await this.initializePlant();
    await this.initializeQueues();
    await this.ewmPlantCacheService.synchronizeInMemoryWorkCenters();
    await this.ewmPlantCacheService.synchronizeInMemoryMaterials();
    await this.ewmPlantCacheService.synchronizeInMemoryStorageLocations();
  }

  public async handleWorkcenterMessage(): Promise<void> {
    const context: JobsLogContext = {
      method: 'handleWorkcenterMessage',
      service: 'DaprService',
    };
    this.customLogger.log(`Received workcenter notification update`, context);
    await this.ewmPlantCacheService.synchronizeInMemoryWorkCenters();
  }

  public async handleMaterialMessage(): Promise<void> {
    const context: JobsLogContext = {
      method: 'handleMaterialMessage',
      service: 'DaprService',
    };
    this.customLogger.log(`Received material notification update`, context);
    await this.ewmPlantCacheService.synchronizeInMemoryMaterials();
  }

  public async handleStorageLocationMessage(): Promise<void> {
    const context: JobsLogContext = {
      method: 'handleStorageLocationMessage',
      service: 'DaprService',
    };
    this.customLogger.log(
      `Received storageLocation notification update`,
      context,
    );
    await this.ewmPlantCacheService.synchronizeInMemoryStorageLocations();
  }

  /**
   * Process the message
   * @param message Mapped Data to process
   */
  private async processMessage(message: RedisMessage): Promise<void> {
    const context: JobsLogContext = {
      method: 'processMessage',
      service: 'DaprService',
    };
    const { destination, ingestionEventTracking, operation, mappedData } =
      message;
    try {
      if (!operation) {
        return;
      }
      if (operation !== 'r' && ingestionEventTracking) {
        const validateAndTrackIngestionEventTracking: boolean =
          await validateAndTrackChanges(
            this.customLogger,
            this.ingestionEventTrackingService,
            ingestionEventTracking,
          );
        if (!validateAndTrackIngestionEventTracking) {
          return;
        }
        await this.ingestionEventTrackingService.upsertCache(
          ingestionEventTracking,
        );
      }
      await emitCosmosEvent(
        this.customLogger,
        context,
        this.eventEmitter,
        destination,
        mappedData,
        operation,
      );
    } catch (error) {
      this.customLogger.error(
        `Error processing Message for ${destination}: ${error.message}`,
        context,
        error.stack,
      );
    }
  }

  /**
   * Process Message Queue
   * @param queueKey Queue Key
   */
  private async processMessageQueue(queueKey: string): Promise<void> {
    const context: JobsLogContext = {
      method: 'processMessageQueue',
      service: 'DaprService',
    };
    // Mark processing as ongoing for this queue
    this.processingQueue[queueKey] = true;
    const processNextMessage = async (): Promise<void> => {
      try {
        // Exit if the queue is empty
        if (
          this.inMemoryQueue[queueKey as keyof typeof this.inMemoryQueue]
            .length === 0
        ) {
          this.customLogger.debug(
            `No messages left in queue ${queueKey}.`,
            context,
          );
          return; // Exit when there are no more messages to process
        }

        // Process the first message in the queue
        const message =
          this.inMemoryQueue[queueKey as keyof typeof this.inMemoryQueue][0];
        if (message) {
          try {
            this.customLogger.debug(
              `Processing message: ${JSON.stringify(message)} for ${queueKey}`,
              context,
            );
            await this.processMessage(message); // Process the message

            this.customLogger.debug(
              `Message processed for ${queueKey}, removing from queue.`,
              context,
            );
            await removeMessageQueue(
              this.customLogger,
              this.serviceMutexes,
              this.daprClient,
              {
                inMemoryQueue: this.inMemoryQueue,
                processingQueue: this.processingQueue,
                queueKey,
                redisStoreNameAmr: this.redisConfigService.redisStoreAmr,
              },
              message,
            ); // Remove the processed message
          } catch (error) {
            this.customLogger.error(
              `Error processing message for ${queueKey}: ${error.message}`,
              context,
              error.stack,
            );
            await moveToDeadLetterQueue(
              this.customLogger,
              context,
              this.redisConfigService.redisStoreAmr,
              this.daprClient,
              queueKey,
              message,
              MESSAGE_ACTION.ERROR,
            ); // Move to DLQ if error occurs
          }

          // Continue processing the next message
          await processNextMessage(); // Recursive call to process the next message
        }
      } catch (error) {
        this.customLogger.error(
          `Error retrieving Redis queue for ${queueKey}: ${error.message}`,
          context,
          error.stack,
        );
      }
    };

    try {
      await processNextMessage(); // Start processing with the recursive function
    } finally {
      // Reset the processing flag to indicate processing is complete
      this.processingQueue[queueKey] = false;
      this.customLogger.debug(
        `Finished processing queue for ${queueKey}.`,
        context,
      );
    }
  }

  /**
   * Message handler
   * @param record - The record to handle
   * @returns Start the dapr server
   */
  public async handleMessage(
    record: CombinedDtoWithIndex,
  ): Promise<{ processed: boolean; reason?: string }> {
    const contextLog: JobsLogContext = {
      method: 'handleMessage',
      service: 'DaprService',
    };
    incrementPendingMessageCount();
    const dateStart = Date.now();
    try {
      if (!checkPayloadConsistency(this.customLogger, contextLog, record))
        return { processed: false, reason: 'Payload consistency check failed' };
      const { __source_table: sourceTable, __op: operation } = record;
      this.customLogger.log(
        `Received - operation: ${operation} - payload: ${JSON.stringify(record)}`,
        contextLog,
      );
      if (!sourceTable)
        return { processed: false, reason: 'Source table is missing' };

      const destination = this.mappingService.getDestinationTable(sourceTable);
      const queueKey = destination;
      const context: AppendAndSaveToCacheQueueInterface = {
        customLogger: this.customLogger,
        daprClient: this.daprClient,
        data: {
          key: queueKey,
          operation,
          record,
          sourceTable,
        },
        inMemoryQueue: this.inMemoryQueue,
        plantList: this.plantList,
        processingQueue: this.processingQueue,
        redisStoreNameAmr: this.redisConfigService.redisStoreAmr,
        services: {
          mappingService: this.mappingService,
          serviceMutexes: this.serviceMutexes,
        },
      };
      await appendAndSaveToCacheQueue(context);

      if (this.processingQueue[queueKey]) {
        this.customLogger.debug(
          `message ${queueKey}is already in processing`,
          contextLog,
        );
        return {
          processed: false,
          reason: `message ${queueKey} is already in processing`,
        };
      }
      this.customLogger.debug(
        `Starting message queue ${queueKey} processing`,
        contextLog,
      );
      this.processMessageQueue(queueKey);
      return { processed: true };
    } catch (error) {
      this.customLogger.error(
        `Error handling Message: ${error.message}`,
        contextLog,
        error.stack,
      );
      return { processed: false, reason: 'error' };
    } finally {
      if (record) {
        await execAndLog(
          this.customLogger,
          async () => {},
          {
            name: 'handleMessage function runtime',
            srcLocation: 'handleMessage',
          },
          {
            record,
          },
          dateStart,
        );
      }
      decrementPendingMessageCount();
    }
  }
}

