/**
 * Converts an ISO 8601 date string to a compact UTC format: YYYYMMDDHHMMSS
 * @param date - A valid ISO date string (e.g. "2025-04-02T13:22:47.167Z")
 * @returns A formatted string in the format YYYYMMDDHHMMSS
 */
export function formatDateToCompactUTC(date: Date): string {
  const YYYY = date.getUTCFullYear();
  const MM = String(date.getUTCMonth() + 1).padStart(2, '0');
  const DD = String(date.getUTCDate()).padStart(2, '0');
  const HH = String(date.getUTCHours()).padStart(2, '0');
  const mm = String(date.getUTCMinutes()).padStart(2, '0');
  const SS = String(date.getUTCSeconds()).padStart(2, '0');

  return `${YYYY}${MM}${DD}${HH}${mm}${SS}`;
}

import { JobsLogContext } from '@mesx/common-lib';
import { MutexInterface, withTimeout, E_TIMEOUT, Mutex } from 'async-mutex';
import { AppLogger } from '@/common/logger/app-logger';
import { asyncSleep } from '@/common/sleep/sleep';

/**
 * Get the lock from mutex
 * @param customLogger application logger
 * @param context app job logger
 * @param serviceMutexes mutex register
 * @param queueKey to get the right mutex instance
 * @param timeoutMs lock acquiring timeout
 * @param retryCount # of retry
 * @param retryDelayMs time between retries
 * @returns releaser function
 */
export async function acquireLockWithTimeout(
  customLogger: AppLogger,
  context: JobsLogContext,
  serviceMutexes: Record<string, Mutex>,
  queueKey: string,
  timeoutMs = 5000,
  retryCount = 3, // Number of retry attempts
  retryDelayMs = 1000, // Delay between retries in milliseconds
): Promise<MutexInterface.Releaser | undefined> {
  let lastError: Error | undefined;
  let attempt = 1;
  const acquireLock = async (): Promise<
    MutexInterface.Releaser | undefined
  > => {
    try {
      return await withTimeout(serviceMutexes[queueKey], timeoutMs).acquire();
    } catch (error) {
      lastError = error;
      if (error === E_TIMEOUT) {
        customLogger.warn(
          `Timeout while acquiring lock for ${queueKey} (Attempt ${attempt} of ${retryCount})`,
          context,
        );
      } else {
        customLogger.error(
          `Error acquiring lock for ${queueKey} (Attempt ${attempt} of ${retryCount}): ${error.message}`,
          context,
          error.stack,
        );
      }

      if (attempt < retryCount) {
        await asyncSleep(retryDelayMs);
        attempt += 1;
        return acquireLock();
      }
    }
    // Log the final failure
    if (lastError) {
      customLogger.error(
        `Failed to acquire lock for ${queueKey} after ${retryCount} attempts: ${lastError.message}`,
        context,
      );
    }

    return undefined;
  };

  return acquireLock();
}

export interface MetricsLog {
  logType: string;
  daprMetrics?: DaprMetrics;
  osMetrics?: OsMetrics;
  processMetrics: ProcessMetrics;
}

export interface DaprMetrics {
  goMemstatsHeapAlloc: number;
  residentMemory: number;
}

export interface OsMetrics {
  cpuLoadAvg1?: number;
  cpuLoadAvg5?: number;
  cpuLoadAvg15?: number;
  freeMemory: number;
  totalMemory: number;
}

export interface ProcessMetrics {
  rss: number;
  heapTotal: number;
  heapUsed: number;
  external: number;
  arrayBuffers: number;
}

import * as os from 'node:os';
import { JobsLogContext } from '@mesx/common-lib';
import axios from 'axios';
import {
  OsMetrics,
  DaprMetrics,
  MetricsLog,
  ProcessMetrics,
} from './log-metrics-type';
import { AppLogger } from '@/common/logger/app-logger';

/**
 * Retrieve container metrics
 * @returns os metrics
 */
function getOSMetrics(): OsMetrics {
  const cpuLoadAvg = os.loadavg();
  return {
    cpuLoadAvg1: cpuLoadAvg.shift(),
    cpuLoadAvg5: cpuLoadAvg.shift(),
    cpuLoadAvg15: cpuLoadAvg.shift(),
    freeMemory: os.freemem() / (1024 * 1024),
    totalMemory: os.totalmem() / (1024 * 1024),
  };
}

/**
 * Retrieve process metrics
 * @returns process metrics
 */
function getProcessMetrics(): ProcessMetrics {
  const processMetrics = process.memoryUsage();
  processMetrics.arrayBuffers /= 1024 * 1024;
  processMetrics.external /= 1024 * 1024;
  processMetrics.heapTotal /= 1024 * 1024;
  processMetrics.heapUsed /= 1024 * 1024;
  processMetrics.rss /= 1024 * 1024;
  return processMetrics;
}

/**
 * Function to extract CPU and memory usage from Dapr metrics
 * @param metrics metrics http results
 * @returns metrics
 */
function extractDaprSideCarMetrics(metrics: string): DaprMetrics {
  const residentMemoryRegex = /process_resident_memory_bytes\s+([\d+.e]+)/; // Handle scientific notation
  const goMemstatsHeapAllocRegex = /go_memstats_heap_alloc_bytes\s+([\d+.e]+)/; // Handle scientific notation

  const residentMemoryMatch = residentMemoryRegex.exec(metrics);
  const goMemstatsHeapAllocMatch = goMemstatsHeapAllocRegex.exec(metrics);

  const residentMemory = residentMemoryMatch
    ? Number.parseFloat(residentMemoryMatch[1]) / (1024 * 1024)
    : 0; // Convert bytes to MB
  const goMemstatsHeapAlloc = goMemstatsHeapAllocMatch
    ? Number.parseFloat(goMemstatsHeapAllocMatch[1]) / (1024 * 1024)
    : 0; // Convert bytes to MB

  return {
    goMemstatsHeapAlloc: Number.parseFloat(goMemstatsHeapAlloc.toFixed(2)), // In MB
    residentMemory: Number.parseFloat(residentMemory.toFixed(2)), // In MB
  };
}

export class LogMetricsWorker {
  private readonly metricsUrl: string;

  private readonly customLogger: AppLogger;

  private workerThreadId: number | undefined = undefined;

  public constructor(
    customLogger: AppLogger,
    protocol = 'http',
    host = 'localhost',
    port = 9090,
  ) {
    this.customLogger = customLogger;
    this.metricsUrl = `${protocol}://${host}:${port}/metrics`;
  }

  /**
   * Get dapr metrics
   * @returns dapr metrics
   */
  private async getDaprSideCarMetrics(): Promise<DaprMetrics | undefined> {
    const context: JobsLogContext = {
      method: 'getDaprSideCarMetrics',
      service: 'logMetricsWorker',
    };
    try {
      const response = await axios.get(this.metricsUrl);
      const metrics = response.data;
      return extractDaprSideCarMetrics(metrics);
    } catch (error) {
      this.customLogger.error(
        `Error fetching Dapr metrics ${this.metricsUrl}: ${error.message}`,
        context,
        error.stack,
      );
    }
    return undefined;
  }

  /**
   * Retrieve dapr and os metrics
   * then log the metrics
   */
  private async logMetrics(): Promise<void> {
    const context: JobsLogContext = {
      method: 'logMetrics',
      service: 'logMetricsWorker',
    };
    const metricsLog: MetricsLog = {
      daprMetrics: await this.getDaprSideCarMetrics(),
      logType: 'Metrics',
      osMetrics: getOSMetrics(),
      processMetrics: getProcessMetrics(),
    };
    this.customLogger.log(JSON.stringify(metricsLog), context);
  }

  /**
   * Function to start the worker
   * that performs regular getMetrics calls
   * @param interval interval in ms
   */
  public startWorker(interval = 1000): void {
    const context: JobsLogContext = {
      method: 'startWorker',
      service: 'logMetricsWorker',
    };
    if (this.workerThreadId) {
      this.customLogger.log('Worker is already running.', context);
      return;
    }

    this.customLogger.log('Starting worker...', context);

    this.workerThreadId = setInterval(
      () => this.logMetrics(),
      interval,
    ) as unknown as number;
  }

  /**
   * Function to stop the worker
   */
  public stopWorker(): void {
    const context: JobsLogContext = {
      method: 'stopWorker',
      service: 'logMetricsWorker',
    };
    if (!this.workerThreadId) return;
    clearInterval(this.workerThreadId);
    this.workerThreadId = undefined;
    this.customLogger.log('Worker stopped.', context);
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { acquireLockWithTimeout } from '../locks/acquire-lock';
import { checkEkanbanTemporaryBufferization } from '../validations/check-ekanban-temporary-bufferization';
import { checkPlantConsistency } from '../validations/check-plant-consistency';
import { AppendAndSaveToCacheQueueInterface } from './interfaces/append-and-save-to-cache-queue.interface';
import { moveToDeadLetterQueue } from './move-to-dead-letter-queue';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { MESSAGE_ACTION } from '@/dapr/interface/enum-message-action.interface';

/**
 * Update the cache of Queue
 * @param context The context object containing all necessary parameters
 * @param context.customLogger Application logger
 * @param context.daprClient used to move to dead letter queue
 * @param context.redisStoreNameAmr used for dapr state store
 * @param context.services services
 * @param context.services.mappingService Mapping service to transform payload
 * @param context.services.serviceMutexes mutex register
 * @param context.inMemoryQueue inMemory queue
 * @param context.processingQueue Process queue to check if it is processing
 * @param context.plantList list of plants
 * @param context.data input data
 * @param context.data.key Key of the queue
 * @param context.data.operation Operation
 * @param context.data.record Record
 * @param context.data.sourceTable Source Table
 * @param context.redisConfigService all redis config service
 * @returns void
 */
export async function appendAndSaveToCacheQueue(
  context: AppendAndSaveToCacheQueueInterface,
): Promise<void> {
  const {
    customLogger,
    daprClient,
    redisStoreNameAmr,
    services,
    inMemoryQueue,
    processingQueue,
    plantList,
    data,
  } = context;
  const { mappingService, serviceMutexes } = services;
  const { key, record, sourceTable, operation } = data;

  const dateFunctionStart = Date.now();
  const logOperationInfo = {
    name: '',
    srcLocation: 'appendAndSaveToCacheQueue',
  };
  const logOperationDetail = {
    key,
  };
  const contextLog: JobsLogContext = {
    method: 'appendAndSaveToCacheQueue',
    service: 'queues',
  };
  try {
    customLogger.verbose(`Start appending queue ${key}`, contextLog);
    const { mappedData, destination, ingestionEventTracking } =
      mappingService.mapData(sourceTable, record, plantList);
    // Check first if there is two table source in the mapping system
    // Fifo check
    customLogger.log(`Maped Data ${JSON.stringify(mappedData)}`, contextLog);
    if (!checkPlantConsistency(customLogger, mappedData, plantList)) return;
    if (
      sourceTable === 'TRANSFER_LOG' &&
      plantList.find((p) => p.plantId === Number(mappedData.plant))
        ?.bufferization === false &&
      record?.POKA_YOKE === 'TRF_F'
    ) {
      customLogger.log(
        `Skipping TRANSFER_LOG event for plant ${mappedData.plant} because bufferization is false`,
        contextLog,
      );
      return;
    }
    if (
      sourceTable === 'EKANBAN_TEMP' &&
      !checkEkanbanTemporaryBufferization(customLogger, mappedData, plantList)
    ) {
      return;
    }
    const newRecord = {
      destination,
      ingestionEventTracking,
      mappedData,
      operation,
      sourceTable,
    };
    logOperationInfo.name = 'Acquire lock';
    const release = await execAndLog(
      customLogger,
      () =>
        acquireLockWithTimeout(customLogger, contextLog, serviceMutexes, key),
      logOperationInfo,
      logOperationDetail,
    );

    if (!release) {
      customLogger.error(
        `Error: Failed to acquire lock for ${key}, skipping processing.`,
        contextLog,
      );
      await moveToDeadLetterQueue(
        customLogger,
        contextLog,
        redisStoreNameAmr,
        daprClient,
        key,
        record,
        MESSAGE_ACTION.APPEND,
      );
      return;
    }

    try {
      logOperationInfo.name = 'Save record in queue cache';
      await execAndLog(
        customLogger,
        async () => inMemoryQueue[key].push(newRecord),
        logOperationInfo,
        logOperationDetail,
      );
    } catch (error) {
      customLogger.error(
        `Error appending and saving queue Message: ${error.message}`,
        contextLog,
        error.stack,
      );
      await moveToDeadLetterQueue(
        customLogger,
        contextLog,
        redisStoreNameAmr,
        daprClient,
        key,
        record,
        MESSAGE_ACTION.APPEND,
      );
    } finally {
      if (!processingQueue[key] && inMemoryQueue[key].length > 1) {
        const processingQueueAlias = processingQueue;
        processingQueueAlias[key] = true;
      }
      customLogger.verbose(
        `End of appending and saving of queue for ${key}`,
        contextLog,
      );
      if (release) {
        if (record) {
          logOperationInfo.name = 'appendAndSaveToCacheQueue function runtime';
          await execAndLog(
            customLogger,
            async () => {},
            logOperationInfo,
            logOperationDetail,
            dateFunctionStart,
          );
        }
        release();
      }
    }
  } catch (error) {
    customLogger.error(
      `Error processing queue:${error.message}`,
      contextLog,
      error.stack,
    );
    await moveToDeadLetterQueue(
      customLogger,
      contextLog,
      redisStoreNameAmr,
      daprClient,
      key,
      record,
      MESSAGE_ACTION.APPEND,
    );
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { DaprClient } from 'dapr-client';
import { KeyValueType } from 'dapr-client/types/KeyValue.type';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { MappedOutput } from '@/common/mapping/interface/mapping.model';

/**
 * Update the cache with FIFO principle
 * @param customLogger - Application logger
 * @param daprClient - Dapr client for State call
 * @param redisStoreNameAmr - Redis store name (AMR) for state call
 * @param key - The cache key
 * @param currentState - The current state
 * @param newRecord - The new record to add to the cache
 * @param newRecord.mappedData - The mapped data
 * @param newRecord.keysValue - The keys value
 * @param newRecord.destination - The destination
 * @param newRecord.sourceTable - The source table
 * @returns void
 */
export async function appendAndSaveToCache(
  customLogger: AppLogger,
  daprClient: DaprClient,
  redisStoreNameAmr: string,
  key: string,
  currentState: string | KeyValueType,
  newRecord: {
    destination: string;
    keysValue: string;
    mappedData: MappedOutput;
    sourceTable: string;
  },
): Promise<void> {
  const context: JobsLogContext = {
    method: 'appendAndSaveToCacheQueue',
    service: 'queues',
  };
  try {
    const oldCachedData = currentState.valueOf()
      ? Object.values(currentState.valueOf())
      : [];
    const dataToCache = {
      key,
      value: [...oldCachedData, newRecord],
    };

    if (currentState.valueOf()) {
      customLogger.log(`Updating state ${key} `, context);
    } else {
      customLogger.log(
        `State ${key} doesn't exist caching ${JSON.stringify(dataToCache)}`,
        context,
      );
    }

    await execAndLog(
      customLogger,
      () => daprClient.state.save(redisStoreNameAmr, [dataToCache]),
      {
        name: 'Save state record in cache',
        srcLocation: 'appendAndSaveToCache',
      },
      {
        key,
      },
    );
  } catch (error) {
    customLogger.error(
      `Failed to append and save to cache ${key}: ${error.message}`,
      context,
      error.stack,
    );
  }
}

