import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '@/common/logger/app-logger';
import { EkanbanTemporaryDto } from '@/modules/ekanban-temp/dtos/ekanban-temporary.dto';
import { EwmPlantCacheService } from '@/modules/ewm-plant-cache/ewm-plant-cache.service';
import { TransferLogDto } from '@/modules/transfer-log/dtos/transfer-log.dto';

type EwmValidationInput = TransferLogDto | EkanbanTemporaryDto;

/**
 * Validates whether a given plant, material, and storage location exist in the EWM cache.
 *
 * Works with either `TransferLogDto` or `EkanbanTemporaryDto`.
 * @param customLogger - Application logger to log verbose and error messages
 * @param mappedData - DTO containing `plant`, `material`, and `toLocation` to validate
 * @param ewmPlantCacheService - Service providing in-memory EWM plant, material, and storage location data
 * @returns `true` if both the storage location and material exist in EWM, `false` otherwise
 */
export async function ewmTransferValidation(
  customLogger: AppLogger,
  mappedData: EwmValidationInput,
  ewmPlantCacheService: EwmPlantCacheService,
): Promise<boolean> {
  const context: JobsLogContext = {
    method: 'ewmTransferValidation',
    service: 'validation',
  };

  try {
    // Extract common properties safely
    const { plant, material, toLocation } = mappedData;

    let materialExisting = false;

    // Check storage location
    const storageLocationList =
      await ewmPlantCacheService.getInMemoryStorageLocations();
    const storageLocationExisting =
      storageLocationList[plant]?.includes(toLocation) ?? false;

    if (!storageLocationExisting) {
      customLogger.verbose(
        `Storage location ${toLocation} is not defined in the EWM list for plant ${plant}`,
        context,
      );
    }

    if (storageLocationExisting) {
      const materialList = await ewmPlantCacheService.getInMemoryMaterials();
      materialExisting = materialList[plant]?.includes(material) ?? false;

      if (!materialExisting) {
        customLogger.verbose(
          `Material ${material} is not defined in the EWM list for plant ${plant}`,
          context,
        );
      }
    }

    return storageLocationExisting && materialExisting;
  } catch (error) {
    customLogger.error(
      `Error processing message: ${error.message}`,
      context,
      error.stack,
    );
    return false;
  }
}

import { JobsLogContext } from '@mesx/common-lib';
import { AppLogger } from '@/common/logger/app-logger';
import { IngestionEventTrackingDTO } from '@/modules/ingestion-event-tracking/ingestion-event-tracking.dto.';
import { IngestionEventTrackingService } from '@/modules/ingestion-event-tracking/ingestion-event-tracking.service';

/**
 *
 * @param customLogger App logger²
 * @param ingestionEventTrackingService to check timestamp
 * @param ingestionEventTracking - The Ingestion Event tracking Dto
 * @returns - Returns a promise that resolves to a boolean indicating the success of the operation.
 */
export async function validateAndTrackChanges(
  customLogger: AppLogger,
  ingestionEventTrackingService: IngestionEventTrackingService,
  ingestionEventTracking: IngestionEventTrackingDTO,
): Promise<boolean> {
  const context: JobsLogContext = {
    method: 'validateAndTrackChanges',
    service: 'validation',
  };
  if (!ingestionEventTracking) {
    customLogger.verbose(
      'Validation failed: ingestionEventTracking is undefined.',
      context,
    );
    return false;
  }
  const {
    changeLastLsn,
    lastTimestamp,
    destinationTable,
    hashKey,
    keys,
    sourceTable,
  } = ingestionEventTracking;
  if (
    changeLastLsn === undefined ||
    lastTimestamp === undefined ||
    hashKey === undefined ||
    keys === undefined ||
    sourceTable === undefined
  ) {
    customLogger.verbose(
      `Validation failed: Missing properties in ingestionEventTracking. ` +
        `Received changeLastLsn: ${changeLastLsn}, lastTimestamp: ${lastTimestamp}, ` +
        `destinationTable: ${destinationTable}, hashKey: ${hashKey}, keys: ${keys}, sourceTable: ${sourceTable}.`,
      context,
    );
    return false;
  }
  try {
    const isDataCurrent =
      await ingestionEventTrackingService.verifyAndTrackIngestionEventTrackingCache(
        ingestionEventTracking,
      );

    if (!isDataCurrent) {
      customLogger.warn(
        `Outdated data detected for table "${sourceTable}". ` +
          `Timestamp: ${lastTimestamp}, Last LSN: ${changeLastLsn}.`,
        context,
      );
      return false;
    }

    return true;
  } catch (error) {
    customLogger.error(
      `Error while verifying and tracking ingestion event for table "${sourceTable}": ${error.message}`,
      context,
      error.stack,
    );
    return false;
  }
}

