@Injectable()
export class ContainerService {
  public constructor(
    private readonly cosmosDatabaseService: ContainerCosmosDatabaseService, // Inject Cosmos DB service
    private readonly ewmPlantCacheService: EwmPlantCacheService,
    private readonly sendEventService: SendEventService, // Inject Send Event service;
    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('container.c')
  private async create(payload: ContainerDto): Promise<void> {
    const context: JobsLogContext = {
      method: 'create',
      object: payload.containerId,
      plant: payload.plant,
      service: 'ContainerService',
    };
    if (!payload)
      return this.customLogger.verbose(`payload is empty${payload}`, context);
    try {
      const containerDto: ContainerDto = payload;
      const isEwmFlow = await ewmContainerValidation(
        this.customLogger,
        payload,
        this.ewmPlantCacheService,
      ); // Check workcenter and material
      if (!isEwmFlow) {
        return undefined;
      }
      // Functional Validation for payload
      if (validatePayload(containerDto)) {
        const upsertContainerDto: UpsertContainerDto = {
          containerId: payload.containerId,
          currentStorageLocation: payload.storageLocation,
          plant: payload.plant,
        };
        await this.cosmosDatabaseService.upsertContainer(upsertContainerDto);

        await this.sendEventService.sendEventContainer('HuMoved', payload);
      } else {
        this.customLogger.verbose(
          `Payload validation failed for container ${containerDto.containerId} for plant ${containerDto.plant}`,
          context,
        );
        return undefined;
      }
    } catch (error) {
      this.customLogger.error(
        `error in insert in data base and publish message: ${error.message}`,
        context,
        error.stack,
      );
      throw new HttpException(
        `error in inserting data ${error}`,
        HttpStatus.BAD_REQUEST,
      );
    }
    return undefined;
  }

  @OnEvent('container.u')
  private async updateByContainerIdAndPlant(
    payload: ContainerDto,
  ): Promise<void> {
    const context: JobsLogContext = {
      method: 'updateByContainerIdAndPlant',
      object: payload.containerId,
      plant: payload.plant,
      service: 'ContainerService',
    };
    const { containerId, plant } = payload;

    if (!payload)
      return this.customLogger.verbose(`payload is empty${payload}`, context);
    try {
      const containerDto: ContainerDto = payload;
      // Check if the container exists in Cosmos DB
      const exists =
        await this.cosmosDatabaseService.findElementByIdAndPartitionKey(
          plant,
          containerId,
        );

      if (!exists) {
        const isEwmFlow = await ewmContainerValidation(
          this.customLogger,
          payload,
          this.ewmPlantCacheService,
        );

        if (isEwmFlow) {
          if (!validatePayload(containerDto)) {
            this.customLogger.error(
              `Payload validation failed for container ${payload.containerId} for plant ${payload.plant}`,
              context,
            );
            return undefined;
          }

          const upsertContainerDto: UpsertContainerDto = {
            containerId: payload.containerId,
            currentStorageLocation: payload.storageLocation,
            plant: payload.plant,
          };

          await this.cosmosDatabaseService.upsertContainer(upsertContainerDto);

          await this.sendEventService.sendEventContainer('HuMoved', payload);
        }
      }

      const containerInCosmos = await this.cosmosDatabaseService.getContainer(
        payload.containerId,
        payload.plant,
      );

      if (exists) {
        if (containerDto.status !== 'PRODUCED') {
          await this.cosmosDatabaseService.deleteContainer(payload);
          return undefined;
        }

        if (
          containerInCosmos !== undefined &&
          containerDto.storageLocation ===
            containerInCosmos.currentStorageLocation
        ) {
          return undefined;
        }
        // Upsert logic for new and updated containers
        const upsertContainerDto: UpsertContainerDto = {
          containerId: payload.containerId,
          currentStorageLocation: payload.storageLocation,
          plant: payload.plant,
        };

        await this.cosmosDatabaseService.upsertContainer(upsertContainerDto);

        await this.sendEventService.sendEventContainer('HuMoved', payload);
      }
    } catch (error) {
      this.customLogger.error(
        `Error updating container: ${error.message}`,
        context,
        error.stack,
      );
      throw new HttpException(
        `error in updating data ${error}`,
        HttpStatus.BAD_REQUEST,
      );
    }
    return undefined;
  }
}

