@Injectable()
export class EkanbanTemporaryService {
  public constructor(
    private readonly sendEventService: SendEventService,
    private readonly ewmPlantCacheService: EwmPlantCacheService,
    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('ekanbanTemp.d')
  private async deleteEkanban(payload: EkanbanTemporaryDto): Promise<void> {
    const context: JobsLogContext = {
      method: 'delete',
      object: payload?.material,
      plant: payload?.plant,
      service: 'EkanbanTemporaryService',
    };

    if (!payload) {
      this.customLogger.verbose(`Payload is empty`, context);
      return;
    }

    // Create a copy and ensure workCenter is always a string
    const updatedPayload: EkanbanTemporaryDto = {
      ...payload,
      workCenter: payload.workCenter ?? '',
    };

    try {
      // Perform EWM validation directly with Ekanban DTO
      const isEwmFlow = await ewmTransferValidation(
        this.customLogger,
        updatedPayload,
        this.ewmPlantCacheService,
      );

      if (!isEwmFlow) {
        this.customLogger.verbose(
          `EWM validation failed for material ${updatedPayload.material}, plant ${updatedPayload.plant}. Skipping event send.`,
          context,
        );
        return;
      }

      // Send event only if validation passes
      await this.sendEventService.sendEventEkanbanTemp(
        'transferMoved',
        updatedPayload,
      );

      this.customLogger.verbose(
        `Ekanban event sent successfully for material ${updatedPayload.material}, plant ${updatedPayload.plant}.`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Error handling delete event: ${error.message}`,
        context,
        error.stack,
      );
    }
  }
}

