    @Inject(CACHE_MANAGER) private readonly cacheManager: Cache,
    private readonly plantHYRApi: PlantHierarchyApi,
    private readonly masterApi: MasterApi,
    private readonly customLogger: AppLogger,
  ) {}

  public async getInMemoryPlants(): Promise<Array<number>> {
    const plantList = await this.cacheManager.get<string>('ewmPlant');
    return plantList ? JSON.parse(plantList) : [];
  }

  public async synchronizeInMemoryPlants(
    plants: Array<PlantsResponseDto>,
  ): Promise<Array<number>> {
    const context: JobsLogContext = {
      method: 'synchronizeInMemoryPlants',
      service: 'EwmPlantCacheService',
    };
    try {
      const cacheKey = 'ewmPlant';
      let plantIds: Array<number> = [];
      plantIds = plants.map((plant) => plant.plantId);
      await this.cacheManager.set(cacheKey, JSON.stringify(plantIds), 0);

      return plantIds;
    } catch (error) {
      this.customLogger.error(
        `ewm material list cached error  ${error.message}`,
        context,
        error.stack,
      );
      return [];
    }
