  public async synchronizeInMemoryWorkCenters(): Promise<void> {
    const context: JobsLogContext = {
      method: 'synchronizeInMemoryWorkCenters',
      service: 'EwmPlantCacheService',
    };
    try {
      const cacheKey = 'ewmWorkcenter';
      const plantList = await this.getInMemoryPlants();
      const workcenters = await this.plantHYRApi.fetchEwmWorkcenter(plantList);
