      return {}; // Ensures the return type always matches
    }

    if (typeof storageLocationList === 'object') {
      return storageLocationList as Record<number, Array<string>>;
    }
    return JSON.parse(storageLocationList) as Record<number, Array<string>>;
  }

  public async getInMemoryWorkcenters(): Promise<
    Record<number, Array<string>>
  > {
    const workcenterList = await this.cacheManager.get<string>('ewmWorkcenter');
    if (!workcenterList) {
      return {}; // Ensures the return type always matches
    }

    if (typeof workcenterList === 'object') {
      return workcenterList as Record<number, Array<string>>;
    }
    return JSON.parse(workcenterList) as Record<number, Array<string>>;
  }

  public async getInMemoryMaterials(): Promise<Record<number, Array<string>>> {
    const materialList = await this.cacheManager.get<string>('ewmMaterial');

    if (!materialList) {
      return {}; // Ensures the return type always matches
    }

    if (typeof materialList === 'object') {
      return materialList as Record<number, Array<string>>;
    }
    return JSON.parse(materialList) as Record<number, Array<string>>;
  }
}

