    EwmPlantCacheModule,
  ],
  providers: [TransferLogService],
})
export class TransferLogModule {}

import { JobsLogContext } from '@mesx/common-lib';
import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { OnEvent } from '@nestjs/event-emitter';
import { EwmPlantCacheService } from '../ewm-plant-cache/ewm-plant-cache.service';
import { TransferLogDto } from './dtos/transfer-log.dto';
import { AppLogger } from '@/common/logger/app-logger';
import { SendEventService } from '@/common/send-event/send-event.service';
import { TransferLogDatabaseService } from '@/cosmos-db/transfer-log-cosmos.database.service';
import { ewmTransferValidation } from '@/helpers/validations/ewm-trf-validation';

@Injectable()
export class TransferLogService {
  public constructor(
    private readonly cosmosDatabaseService: TransferLogDatabaseService,
    private readonly ewmPlantCacheService: EwmPlantCacheService,
    private readonly sendEventService: SendEventService,
    private readonly customLogger: AppLogger,
  ) {}

  @OnEvent('transferLog.c')
  private async create(payload: TransferLogDto): Promise<void> {
    const context: JobsLogContext = {
      method: 'create',
      object: payload.material,
      plant: payload.plant,
      service: 'TransferLogService',
    };

    if (!payload) {
      return this.customLogger.verbose(`payload is empty${payload}`, context);
    }

    try {
      const transferLogDto: TransferLogDto = payload;

      const isEwmFlow = await ewmTransferValidation(
        this.customLogger,
        transferLogDto,
        this.ewmPlantCacheService,
      );

      if (!isEwmFlow) {
        this.customLogger.verbose(
          `EWM validation failed for material ${transferLogDto.material}, skipping Cosmos lookup.`,
          context,
        );
        return undefined;
      }

      const { plant, seqNum } = transferLogDto;

      const existingRecord =
        await this.cosmosDatabaseService.findTransferBySeqNumAndPartitionKey(
          plant,
          seqNum,
        );

      if (existingRecord) {
        this.customLogger.verbose(
          `Transfer log already exists for plant ${plant}, seqNum ${seqNum}. Skipping EWM send.`,
          context,
        );
        return undefined;
      }

      await this.cosmosDatabaseService.upsertTransferLog(transferLogDto);

      await this.sendEventService.sendEventTransfer(
        'transferMoved',
        transferLogDto,
        transferLogDto.pokaYoke,
      );
    } catch (error) {
      this.customLogger.error(
        `error in insert in data base and publish message: ${error.message}`,
        context,
        error.stack,
      );
      throw new HttpException(
        `error in inserting data ${error}`,
        HttpStatus.BAD_REQUEST,
      );
    }
    return undefined;
  }
}

